using AiGateway.Api.Contracts;using AiGateway.Application;using AiGateway.Domain;
namespace AiGateway.Api.Middleware;
public sealed class SafeExceptionMiddleware(RequestDelegate next,ILogger<SafeExceptionMiddleware> logger,ISensitiveDataSanitizer sanitizer)
{public async Task InvokeAsync(HttpContext context){try{await next(context);}catch(OperationCanceledException)when(context.RequestAborted.IsCancellationRequested){context.Response.StatusCode=499;}catch(AiGatewayException ex){logger.LogWarning("AI request failed: {Code}",ex.Code);await Write(context,Status(ex.Code),ex.Code,ex.SafeMessage);}catch(Exception ex){logger.LogError("Unhandled AI error: {SafeError}",sanitizer.Sanitize(ex.Message));await Write(context,500,"AI_INTERNAL_ERROR","Não foi possível processar a solicitação.");}}private static int Status(string code)=>code switch{ErrorCodes.AccessDenied=>403,ErrorCodes.InvalidInput=>400,ErrorCodes.InsufficientKnowledge=>422,ErrorCodes.Timeout=>504,ErrorCodes.UnsupportedTool=>422,_=>503};private static async Task Write(HttpContext context,int status,string code,string message){context.Response.StatusCode=status;await context.Response.WriteAsJsonAsync(new ErrorContract(context.Items["RequestId"]?.ToString()??context.TraceIdentifier,code,message));}}
